// План specs/admin-plans.md 4.1 (кейс AP-12). Две роли, ТОЛЬКО ЧТЕНИЕ: admin смотрит строку «בדיקה» в Plans, «בדיקה» — своё меню и Billing.
// Ничего не сохраняет (диалоги не открываются). @prod-safe
// Проверяет правило resolve_active_plan: тариф/источник в Plans = то, что действует у пользователя.
import { test, expect } from '../../fixtures';
import { setLanguage, openPlansTab, targetRow, enDate } from './plans-helpers';
import {
  cellValue, menuLink, expectMenuLoaded, openBilling, anyGrantedBadge, grantedBadge,
  AI_PLANS, INVENTORY_PLANS, KNOWN_PLANS, blockStripe,
} from './plans-read-helpers';

/** «Oct 19, 2026» → полночь этой даты (локально). */
function parseEnDate(text: string): Date {
  const d = new Date(text);
  expect(Number.isNaN(d.getTime()), `«${text}» — не дата`).toBe(false);
  return d;
}

test.describe('Admin Panel — Plans: active plan for the user', () => {
  test('Plans row of «בדיקה» shows the plan and source the user actually has #2b3784 #b42657 @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'en');
    const adminStripe = await blockStripe(admin);
    const userStripe = await blockStripe(user);

    // 1. Admin: строка «בדיקה» (ровно одна)
    await openPlansTab(admin);
    const row = await targetRow(admin);
    const plan = await cellValue(admin, row, 'Plan');
    const source = await cellValue(admin, row, 'Source');
    const until = await cellValue(admin, row, 'Until');
    expect(KNOWN_PLANS, `неизвестный тариф «${plan}»`).toContain(plan);
    const assigned = /\bAssigned\b/.test(source);

    if (assigned) {
      // Выдача в силе: дата не в прошлом, есть «Change / extend» и «Revoke» (источник: тикет — выдача действует до даты включительно)
      const today = parseEnDate(enDate(0));
      expect(parseEnDate(until).getTime(), 'истёкшая выдача не должна показываться как Assigned').toBeGreaterThanOrEqual(today.getTime());
      await expect(row.getByRole('button', { name: 'Change / extend', exact: true })).toBeVisible();
      await expect(row.getByRole('button', { name: 'Revoke', exact: true })).toBeVisible();
    } else {
      // Выдачи нет (или истекла): только «Assign plan» (20.10: Techory Lite · Free · Until —)
      await expect(row.getByRole('button', { name: 'Assign plan', exact: true })).toBeVisible();
      await expect(row.getByRole('button', { name: 'Revoke', exact: true })).toHaveCount(0);
    }

    // 2. Пользователь: меню соответствует тарифу из Plans (AI — Pro и выше, Inventory — Starter и выше)
    await user.goto('/dashboard');
    await expectMenuLoaded(user);
    await expect(menuLink(user, 'AI')).toHaveCount(AI_PLANS.includes(plan) ? 1 : 0);
    await expect(menuLink(user, 'Inventory')).toHaveCount(INVENTORY_PLANS.includes(plan) ? 1 : 0);

    // 3. Пользователь: Billing показывает тот же тариф; бейдж выдачи — только при Assigned, с той же датой
    await openBilling(user);
    await expect(user.getByText(plan, { exact: true }).first()).toBeVisible();
    if (assigned) {
      await expect(user.getByText(grantedBadge(until), { exact: true })).toBeVisible();
    } else {
      await expect(anyGrantedBadge(user)).toHaveCount(0);
    }

    expect([...adminStripe, ...userStripe], 'Stripe не должен открываться').toEqual([]);
  });
});
